import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadJaipurData(){const e=readFileSync(resolve(__dirname,"../../jaipur-kingdom-explorer/jaipur-data.js"),"utf-8");return new Function(e+"\nreturn { JAIPUR_INFO, TIMELINE_DATA, RULERS_DATA, CONTRIBUTIONS_DATA, GALLERY_IMAGES, REFERENCES };")()}describe("Kingdom of Jaipur Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadJaipurData()}),describe("JAIPUR_INFO metadata",()=>{it("contains correct Kingdom of Jaipur attributes",()=>{expect(e.JAIPUR_INFO.id).toBe("jaipur-kingdom"),expect(e.JAIPUR_INFO.name).toContain("Kingdom of Jaipur"),expect(e.JAIPUR_INFO.dynasty).toContain("Kachwaha"),expect(e.JAIPUR_INFO.period).toContain("1128")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.JAIPUR_INFO.quickStats)).toBe(!0),expect(e.JAIPUR_INFO.quickStats.length).toBe(6)})}),describe("TIMELINE_DATA & RULERS_DATA",()=>{it("contains milestone timeline items and key rulers including Sawai Jai Singh II",()=>{expect(Array.isArray(e.TIMELINE_DATA)).toBe(!0),expect(e.TIMELINE_DATA.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.RULERS_DATA)).toBe(!0),expect(e.RULERS_DATA.length).toBeGreaterThanOrEqual(4)})}),describe("CONTRIBUTIONS_DATA",()=>{it("contains required contribution fields",()=>{expect(e.CONTRIBUTIONS_DATA.overview).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.plannedCityDesign).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.astronomyJantarMantar).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.architectureForts).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.handicraftsArts).toBeDefined()})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});